#!/usr/bin/env bash
# Step 1 (GPU): the role-playing and default replies, generated by the authors' pipeline/1_generate.py with its default
# settings on Qwen3-8B at the fixed revision, into responses/{role}.jsonl in the data directory. The authors' code runs
# in its own locked environment (vLLM 0.13.0) in its checkout, and skips roles whose output exists.
#
#   steps/1_generate.sh [--shard i/n] [--roles ROLE ...] [--question-count N]
#
# --shard i/n takes the i-th of n parts of the 276 roles (275 roles and default); --roles takes only those roles;
# --question-count N answers only the first N of the 240 questions.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
shard="" roles=() extra=()
while [[ $# -gt 0 ]]; do
  case $1 in
    --shard) shard=$2; shift 2 ;;
    --question-count) extra=(--question_count "$2"); shift 2 ;;
    --roles) shift; while [[ $# -gt 0 && $1 != --* ]]; do roles+=("$1"); shift; done ;;
    *) echo "1_generate.sh: unknown argument $1" >&2; exit 2 ;;
  esac
done

mapfile -t setup < <(SHARD="$shard" ROLES="${roles[*]:-}" uv run python - <<'PY'
import os
from persona_neurons import config
from persona_neurons.shards import shard
from persona_neurons.upstream import fetch_upstream, model_snapshot

checkout = fetch_upstream(config.upstream_dir())
print(checkout)
print(model_snapshot(config.MODEL_ID, config.MODEL_REVISION))
print(config.data_dir() / "responses")
roles = [p.stem for p in (checkout / "data" / "roles" / "instructions").glob("*.json")]
only = os.environ["ROLES"].split()
print(" ".join(shard([r for r in roles if not only or r in only], os.environ["SHARD"] or None)))
PY
)
checkout=${setup[0]} snapshot=${setup[1]} out=${setup[2]}
read -r -a todo <<< "${setup[3]:-}"
[[ ${#todo[@]} -gt 0 ]] || { echo "1_generate.sh: no roles to generate" >&2; exit 1; }
mkdir -p "$out"
echo "generating ${#todo[@]} roles into $out"

cd "$checkout"
unset VIRTUAL_ENV  # this project's environment; the checkout has its own
uv sync --frozen -q
uv run python pipeline/1_generate.py --model "$snapshot" --roles_dir data/roles/instructions \
  --questions_file data/extraction_questions.jsonl --output_dir "$out" --roles "${todo[@]}" "${extra[@]}"
